/* Section Container Spacing & Typography */
.sl-method-text {
    font-family: inherit;
}
.sl-method-text .sl-container-boxed {
    max-width: 1240px;
    margin: 0 auto;
    padding-left: 1.5rem;
    padding-right: 1.5rem;
}
@media (min-width: 992px) {
    .sl-method-text .sl-container-boxed {
        padding-left: 2.5rem;
        padding-right: 2.5rem;
    }
}
.sl-method-text .sl-badge-eyebrow {
    background-color: color-mix(in srgb, var(--smartlearn-primary) 15%, transparent);
    color: var(--smartlearn-primary);
    font-size: 0.85rem;
    font-weight: 750;
    letter-spacing: 0.12em;
}
.sl-method-text .sl-method-heading {
    font-size: clamp(2.2rem, 3.6vw, 3.1rem);
    font-weight: 800;
    line-height: 1.16;
    letter-spacing: -0.035em;
    color: var(--smartlearn-text);
}
.sl-method-text .sl-method-lead {
    font-size: 1.125rem;
    line-height: 1.75;
    color: var(--smartlearn-text-muted);
    opacity: 0.95;
}

/* Pill Accordion List & Capsule Styling */
.sl-method-text .sl-accordion-btn {
    padding: 1.15rem 1.65rem;
    background-color: transparent;
    border: 1.5px solid color-mix(in srgb, var(--smartlearn-primary) 30%, var(--smartlearn-card-border)) !important;
    color: var(--smartlearn-text);
    transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
    cursor: pointer;
    box-shadow: 0 4px 15px rgba(0,0,0,0.02);
}
.sl-method-text .sl-accordion-btn:hover {
    border-color: var(--smartlearn-primary) !important;
    background-color: color-mix(in srgb, var(--smartlearn-primary) 8%, transparent);
    transform: translateX(4px);
}
.sl-method-text .sl-accordion-title {
    font-size: 0.98rem;
    letter-spacing: 0.06em;
    font-weight: 750;
}
.sl-method-text .sl-accordion-icon {
    width: 42px;
    height: 42px;
    background-color: color-mix(in srgb, var(--smartlearn-text) 12%, transparent);
    color: var(--smartlearn-text);
    transition: all 0.35s cubic-bezier(0.16, 1, 0.3, 1);
}
.sl-method-text .sl-accordion-icon i {
    font-size: 14px;
    transition: transform 0.3s ease;
}
.sl-method-text .sl-accordion-item.active .sl-accordion-btn {
    border-color: var(--smartlearn-primary) !important;
    background-color: color-mix(in srgb, var(--smartlearn-primary) 10%, transparent);
}
.sl-method-text .sl-accordion-item.active .sl-accordion-icon {
    background-color: var(--smartlearn-primary);
    color: #FFFFFF !important;
    transform: rotate(90deg);
}
.sl-method-text .sl-accordion-body-wrapper {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.4s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.3s ease;
    opacity: 0;
}
.sl-method-text .sl-accordion-item.active .sl-accordion-body-wrapper {
    max-height: 500px;
    opacity: 1;
}
.sl-method-text .sl-accordion-body {
    padding: 1.25rem 1.5rem 0.5rem 1.25rem;
    font-size: 1.05rem;
    line-height: 1.75;
}
.sl-method-text .sl-stats-bar {
    background-color: color-mix(in srgb, var(--smartlearn-card-bg) 65%, #000 35%);
    border-color: color-mix(in srgb, var(--smartlearn-card-border) 80%, transparent) !important;
}
.sl-method-text .sl-ring-container {
    width: 76px;
    height: 76px;
}
.sl-method-text .sl-ring-svg {
    transform: rotate(-90deg);
}
.sl-method-text .sl-ring-bg {
    stroke: color-mix(in srgb, var(--smartlearn-text) 15%, transparent);
}
.sl-method-text .sl-ring-fill {
    stroke-linecap: round;
    transition: stroke-dasharray 1.2s cubic-bezier(0.16, 1, 0.3, 1);
}
.sl-method-text .sl-ring-blue {
    stroke: var(--smartlearn-primary);
}
.sl-method-text .sl-ring-teal {
    stroke: #2dd4bf;
}
.sl-method-text .sl-ring-text {
    font-size: 1.25rem;
    font-weight: 800;
    color: var(--smartlearn-text);
}
.sl-method-text .sl-stat-title {
    font-size: 1.18rem;
    line-height: 1.25;
    color: var(--smartlearn-text);
    letter-spacing: -0.01em;
}

js:
(function() {
    const root = document.querySelector('.sl-method-text');
    if (!root) return;

    const accordionItems = root.querySelectorAll('.sl-accordion-item');

    accordionItems.forEach(item => {
        const btn = item.querySelector('.sl-accordion-header');
        if (!btn) return;

        btn.addEventListener('click', (e) => {
            if (document.body.classList.contains('sl-editor-mode')) return;
            e.preventDefault();

            const isOpen = item.classList.contains('active');

            accordionItems.forEach(other => {
                if (other !== item) other.classList.remove('active');
            });

            if (isOpen) {
                item.classList.remove('active');
            } else {
                item.classList.add('active');
            }
        });
    });
})();
